function validate([nums]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 10^5 values.';
  const seen = new Array(n + 1).fill(false);
  for (const value of nums) {
    if (value < 1 || value > n) return 'Each value is between 1 and nums.length.';
    if (seen[value]) return 'nums is a permutation of 1 to n, so no value repeats.';
    seen[value] = true;
  }
  return null;
}

