function uniqueXorTriplets(nums) {
  const n = nums.length;
  // With one or two numbers, every triplet XOR is one of the numbers itself.
  if (n <= 2) {
    return n;
  }
  // Otherwise every value that fits in n's bit length can be made, and nothing larger.
  let bits = 0;
  while ((1 << bits) <= n) {
    bits++;
  }
  return 1 << bits;
}

