function uniqueXorTriplets(nums) {
  // XOR ignores order, so listing every pick (i, j, k) gives the same values as i <= j <= k.
  const pairs = new Set();
  for (const a of nums) {
    for (const b of nums) {
      pairs.add(a ^ b);
    }
  }
  const triplets = new Set();
  for (const pair of pairs) {
    for (const c of nums) {
      triplets.add(pair ^ c);
    }
  }
  return triplets.size;
}

