function generate(rand, size) {
  let n;
  if (size === 'large') {
    // Around powers of two the answer changes, so those lengths are favoured.
    const choices = [2000, 1024, 1023, 1000 + Math.floor(rand() * 1001)];
    n = choices[Math.floor(rand() * choices.length)];
  } else {
    n = 1 + Math.floor(rand() * 12);
  }
  const nums = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
